-- ---------------- 12. PageSetting 三屏种子（Filter/Detail=Front 前端 DynCom；List=Back 后端 partial） ----------------

INSERT INTO PageSetting (Code, Name, SettingType, TableName, ConfigJson, RenderMode, PartialPath, DefaultJson, SortNo, IsActive)
SELECT 'setting-filter-basic', '通用筛选配置', 'Filter', NULL, '{"component":"DynGridContainer","options":{"comoptions":{"direction":"vertical","size":"small"},"labeloptions":{"required":false,"show":false,"labelposition":"right","labelwidth":"150px"},"itemoptions":{"class":"grid grid-cols-4 gap-x-3 gap-y-2 items-center"},"compassthrough":"comoptions.size,labeloptions.labelposition,labeloptions.labelwidth"},"childrenctrls":[{"component":"DynElInput","modelname":"Code.value","options":{"comoptions":{"placeholder":"名称/编码模糊搜索","clearable":true,"size":"small"},"labeloptions":{"label":"关键字","required":false,"show":true},"compassthrough":"comoptions.size,labeloptions.labelposition,labeloptions.labelwidth"}},{"component":"DynElSelect","modelname":"IsActive.value","options":{"comoptions":{"sourceType":"static","optionValues":[{"label":"启用","value":1},{"label":"停用","value":0}],"placeholder":"请选择是否启用","clearable":true,"size":"small"},"labeloptions":{"label":"启用","required":false,"show":true},"compassthrough":"comoptions.size,labeloptions.labelposition,labeloptions.labelwidth"}}]}', 'Front', NULL, '{"Code": {"op": "like", "value": null}, "IsActive": {"op": "eq", "value": null}}', 1, 1
