INSERT INTO PageSetting (Code, Name, SettingType, TableName, ConfigJson, RenderMode, PartialPath, DefaultJson, SortNo, IsActive)
SELECT 'setting-list-basic', '通用列表配置', 'List', NULL, '{"columns":[{"field":"Id","label":"Id","width":90},{"field":"Code","label":"编码","width":180},{"field":"Name","label":"名称","width":220},{"field":"IsActive","label":"启用","width":100,"cellType":"tag"},{"field":"CreateTime","label":"创建时间","width":190}]}', 'Back', '~/Views/DynTemplates/Partials/ListBack.cshtml', '{"pageInfo": {"PageIndex": 1, "PageSize": 20, "TotalCount": 0}, "sort": {"field": "CreateTime", "order": "desc"}}', 2, 1
WHERE NOT EXISTS (SELECT 1 FROM PageSetting WHERE Code='setting-list-basic');
